// selfhost.js — the organism grows ITSELF. Its own code folder is the host (Node).
// An INSTRUCTION is something checkable: a function name, typed inputs, an output type, and examples (input → output).
// Optional: `about` (words — ranked against what it has read to decide which parts to offer first), `use` (constants).
// The units construct it from the toolbox + abilities adopted from repositories + everything it grew before (so growth
// compounds). The gate: every example passes in the grown file on its own, the regression tests still pass. Nothing is
// overwritten: each growth is a new file (name.js, name.v2.js …), logged in grown/log.json, and committed if the folder is a
// git repository (so the history can live on GitHub). A failed or refused attempt is logged too, and changes nothing.
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs"; import { join } from "node:path"; import { execSync } from "node:child_process";
import { enter } from "./morphogenesis.js"; import { softwareHost } from "./hosts.js"; import { runHost } from "./lifecycle.js";
import { TOOLBOX, TYPES } from "./toolbox.js"; import { Corpus, words } from "./research.js";
const J = (p, d) => { try { return JSON.parse(readFileSync(p, "utf8")); } catch { return d; } };

/** Grown functions become parts: each is loaded from its own file (generated by the swarm, already gated). */
export function grownParts(dir) {
  const idx = J(join(dir, "index.json"), []);
  return idx.filter(g => g.active).map(g => { const src = readFileSync(join(dir, g.file), "utf8").replace(/export\s+function/g, "function");
    const run = new Function("args", `${src}\nreturn ${g.name}(${g.params.map(p => "args." + p.id).join(", ")});`);
    return { id: "grown." + g.name, inputs: Object.fromEntries(g.params.map(p => [p.id, p.type])), output: g.outType, dimension: "Evolution", about: g.about ?? "", run, formation: { plan: [], bound: {} } }; });   /* grown before → recalled first, like learned formations */
}
/** Constants an instruction needs but doesn't give: single characters in an output that no input has (a rule, not a list). */
function derived(ins) { const out = new Set();
  for (const e of ins.examples) { if (typeof e.out !== "string") continue; const inText = JSON.stringify(e.args);
    for (const ch of new Set(e.out)) if (!inText.includes(ch) && !/[A-Za-z0-9]/.test(ch)) out.add(ch); }
  for (const e of ins.examples) for (const v of Object.values(e.args)) if (typeof v === "string" && v.includes(" ")) out.add(" ");
  return [...out]; }

/** 58 → 18 → 58: if 18 rejects (fits what it saw, fails what was held back), 58 tries again — up to `tries` times. Every attempt is logged. */
export function growSelf(O, ins, opt = {}) { const tries = opt.tries ?? 3; let r;
  for (let i = 0; i < tries; i++) { r = growOnce(O, ins, opt); if (globalThis.DBG) console.log('attempt', i, r.ok, r.why, r.plan?.join('>'), [...(O.morph?.registry.keys() ?? [])].filter(k => k.startsWith('formation'))); if (r.ok || !/^18 judged/.test(r.why ?? "")) return { ...r, attempts: i + 1 }; }
  return { ...r, attempts: tries }; }
function growOnce(O, ins, { dir = "./grown", abilities = [], corpus = new Corpus(), gate = [], commit = true } = {}) {
  mkdirSync(dir, { recursive: true }); const log = J(join(dir, "log.json"), []), idx = J(join(dir, "index.json"), []), t = new Date().toISOString();
  const say = (entry) => { log.push({ t, name: ins.name, ...entry }); writeFileSync(join(dir, "log.json"), JSON.stringify(log, null, 1)); return entry; };
  // which parts first: what the instruction says, read against what the organism has read (BM25)
  const parts = [...TOOLBOX, ...abilities, ...grownParts(dir)];
  const P = new Corpus(parts.map(p => ({ title: p.id, text: p.about ?? "" }))); for (const d of corpus.export().slice(-200)) P.add({ title: "_read", text: d.text ?? "" });
  const q = `${ins.name} ${ins.about ?? ""}`, rank = new Map(P.search(q, 99).filter(d => d.title !== "_read").map((d, i) => [d.title, i]));
  const ops = parts.filter(p => Object.values(p.inputs).every(t => t in TYPES) && p.output in TYPES).sort((a, b) => (rank.get(a.id) ?? 99) - (rank.get(b.id) ?? 99));
  const consts = [...(ins.use ?? []), ...derived(ins)].map((v, i) => ({ id: "c" + i, type: typeof v === "number" ? "number" : "text", value: v }));
  const mats = [...ins.params.map(p => ({ id: p.id, type: p.type, value: ins.examples[0].args[p.id] })), ...consts];
  /* 18 (correction): with 3+ examples the last is HELD BACK — the units build from the rest; the judgment checks the unseen one */
  const seen = ins.examples.length >= 3 ? ins.examples.slice(0, -1) : ins.examples, heldOut = ins.examples.length >= 3 ? ins.examples.at(-1) : null;
  const call = a => `${ins.name}(${ins.params.map(p => JSON.stringify(a[p.id])).join(", ")})`;
  const testOf = ex => `import { ${ins.name} } from './${ins.name}.js';\n` + ex.map(e => `assert(JSON.stringify(${call(e.args)}) === ${JSON.stringify(JSON.stringify(e.out))});`).join("\n") + "\n", test = testOf(seen);
  const host = softwareHost({ name: "self:" + ins.name, types: TYPES, files: [{ path: "test.js", text: test }], materials: mats, operations: ops,
    requirement: { name: ins.name, path: ins.name + ".js", params: ins.params.map(p => p.id), outType: ins.outType, cases: seen.map(e => ({ args: e.args, out: e.out })) } });
  let r; try { r = enter(O, host); } catch (e) { return say({ ok: false, why: "construction error: " + (e.message ?? e), at: String(e.stack ?? "").split("\n").slice(1, 4).join(" | ") }); }
  const st = n => r.steps.filter(s => s.step === n).at(-1);
  if (!r.ok) return say({ ok: false, why: st("fail")?.reason ?? "not built", steps: r.steps.map(s => s.step) });
  const code = host.app.files.find(f => f.path === ins.name + ".js").text;
  // GATE 1: the grown file on its own meets every example
  if (!runHost([{ path: ins.name + ".js", text: code }, { path: "test.js", text: test }]).ok) return say({ ok: false, why: "grown file failed its examples alone" });
  if (heldOut && !runHost([{ path: ins.name + ".js", text: code }, { path: "test.js", text: testOf([heldOut]) }]).ok)
  { O.morph?.registry.delete(r.cluster); const F = O.morphMemory?.formations; if (F) { const k = F.findLastIndex(f => f.formation === r.cluster); if (k >= 0) F.splice(k, 1); }   /* 18 rejected it: it is not kept as learned */
    return say({ ok: false, why: "18 judged it: fits the examples it saw, fails the one held back (it memorised instead of understanding)", plan: st("construct").plan }); }
  // never overwrite: name.js, then name.v2.js …
  let v = 1, file = `${ins.name}.js`; while (existsSync(join(dir, file))) file = `${ins.name}.v${++v}.js`;
  writeFileSync(join(dir, file), `// grown by the organism ${t} from instruction "${ins.name}" — plan: ${st("construct").plan.join(" → ")} (by ${st("construct").by})\n` + code);
  // GATE 2: regression — the organism's own tests still pass with this growth in place; if not, it stays inactive
  const failed = gate.filter(cmd => { try { execSync(cmd, { stdio: "ignore", timeout: 600000 }); return false; } catch { return true; } });
  for (const g of idx) if (g.name === ins.name && !failed.length) g.active = false;   // the newer growth takes over; older stays on file
  idx.push({ name: ins.name, file, params: ins.params, outType: ins.outType, about: ins.about, plan: st("construct").plan, by: st("construct").by, active: !failed.length, t });
  writeFileSync(join(dir, "index.json"), JSON.stringify(idx, null, 1));
  const entry = say({ ok: !failed.length, file, plan: st("construct").plan, by: st("construct").by, cases: `${st("act+evaluate").casesMet}/${st("act+evaluate").of}`, regressionFailed: failed });
  if (commit) try { execSync(`git -C "${dir}" rev-parse --is-inside-work-tree`, { stdio: "ignore" });
    execSync(`git -C "${dir}" add -A . && git -C "${dir}" commit -q -m ${JSON.stringify(`organism grew ${file}: ${entry.plan.join(" → ")}${failed.length ? " (inactive: regression failed)" : ""}`)}`, { stdio: "ignore" }); entry.committed = true; } catch { entry.committed = false; }
  return entry;
}
/** Run every instruction in a file (JSON list), in order — later ones may build on earlier growth. */
export function growFromFile(O, path, opt) { return J(path, []).map(ins => growSelf(O, ins, opt)); }
